/**
 * Typed client for the `plain_markets` program (programs/plain-markets).
 *
 * - IDL + IDL type are generated by `anchor build` and copied by `scripts/markets-sync-idl.mjs`.
 * - Instruction builders pass every account explicitly (no RPC for account resolution), so they
 *   work offline and in the browser.
 * - Amounts are bigint at the edges; BN only inside Anchor calls.
 */
import { AnchorProvider, BN, BorshCoder, EventParser, Program, type IdlAccounts, type IdlEvents, type IdlTypes, type Provider } from "@anchor-lang/core";
import {
  ASSOCIATED_TOKEN_PROGRAM_ID,
  TOKEN_2022_PROGRAM_ID,
  createAssociatedTokenAccountIdempotentInstruction,
  createTransferCheckedInstruction,
  getAssociatedTokenAddressSync,
} from "@solana/spl-token";
import { type AccountMeta, type Connection, PublicKey, SystemProgram, type TransactionInstruction } from "@solana/web3.js";

import idlJson from "./idl/plain_markets.json";
import type { PlainMarkets } from "./idl/plain_markets";

export type { PlainMarkets };
export const PLAIN_MARKETS_IDL = idlJson as PlainMarkets;
export const PLAIN_MARKETS_PROGRAM_ID = new PublicKey(idlJson.address);

// ---- account / event / type shapes ----------------------------------------------------------------

export type InstrumentAccount = IdlAccounts<PlainMarkets>["instrument"];
export type CorporateActionAccount = IdlAccounts<PlainMarkets>["corporateAction"];
export type ClaimReceiptAccount = IdlAccounts<PlainMarkets>["claimReceipt"];
export type VoteRecordAccount = IdlAccounts<PlainMarkets>["voteRecord"];
export type AllowEntryAccount = IdlAccounts<PlainMarkets>["allowEntry"];
export type OfferingAccount = IdlAccounts<PlainMarkets>["offering"];
export type MarketsEvents = IdlEvents<PlainMarkets>;
export type MarketsEventName = keyof MarketsEvents;
export type MarketsEvent = { [K in MarketsEventName]: { name: K; data: MarketsEvents[K] } }[MarketsEventName];
type T = IdlTypes<PlainMarkets>;
export type InstrumentParamsArg = T["instrumentParams"];
export type AnnounceParamsArg = T["announceParams"];
export type SnapshotParamsArg = T["snapshotParams"];

export type ActionKind = "Coupon" | "PartialRedemption" | "FinalRedemption" | "Vote";
export type ActionStatus = "Announced" | "RecordLocked" | "SnapshotPosted" | "Funded" | "Settling" | "Settled" | "Cancelled";
export type InstrumentStatus = "Active" | "Matured" | "Redeemed";
export type PaymentMode = "Claim" | "Push";

/** Anchor decodes Rust enums as `{ variantName: {} }`; returns "VariantName". */
export function enumName<N extends string>(value: object): N {
  const key = Object.keys(value)[0];
  return (key.charAt(0).toUpperCase() + key.slice(1)) as N;
}

function enumArg(name: string): never {
  return { [name.charAt(0).toLowerCase() + name.slice(1)]: {} } as never;
}

const bn = (v: bigint | number) => new BN(v.toString());
export const toBigInt = (v: BN | bigint | number) => (typeof v === "bigint" ? v : BigInt(v.toString()));
const bytes32 = (b: Uint8Array | number[]) => {
  const arr = Array.from(b);
  if (arr.length !== 32) throw new Error("expected 32 bytes");
  return arr;
};

// ---- PDAs -------------------------------------------------------------------------------------------

const enc = (s: string) => new TextEncoder().encode(s);
const u64le = (v: bigint | number) => {
  const out = new Uint8Array(8);
  new DataView(out.buffer).setBigUint64(0, BigInt(v), true);
  return out;
};
const find = (seeds: Uint8Array[], programId = PLAIN_MARKETS_PROGRAM_ID) => PublicKey.findProgramAddressSync(seeds, programId)[0];

export const pda = {
  instrument: (mint: PublicKey, programId?: PublicKey) => find([enc("instrument"), mint.toBytes()], programId),
  extraAccountMetas: (mint: PublicKey, programId?: PublicKey) => find([enc("extra-account-metas"), mint.toBytes()], programId),
  action: (instrument: PublicKey, id: bigint | number, programId?: PublicKey) =>
    find([enc("action"), instrument.toBytes(), u64le(id)], programId),
  vault: (action: PublicKey, programId?: PublicKey) => find([enc("vault"), action.toBytes()], programId),
  claim: (action: PublicKey, holder: PublicKey, programId?: PublicKey) =>
    find([enc("claim"), action.toBytes(), holder.toBytes()], programId),
  vote: (action: PublicKey, holder: PublicKey, programId?: PublicKey) =>
    find([enc("vote"), action.toBytes(), holder.toBytes()], programId),
  allow: (instrument: PublicKey, wallet: PublicKey, programId?: PublicKey) =>
    find([enc("allow"), instrument.toBytes(), wallet.toBytes()], programId),
  offering: (instrument: PublicKey, programId?: PublicKey) => find([enc("offering"), instrument.toBytes()], programId),
  /** Issuance proceeds vault (token account owned by the offering PDA). */
  proceeds: (instrument: PublicKey, programId?: PublicKey) => find([enc("proceeds"), instrument.toBytes()], programId),
};

export const bondAta = (owner: PublicKey, mint: PublicKey) => getAssociatedTokenAddressSync(mint, owner, true, TOKEN_2022_PROGRAM_ID);

/** Extra accounts Token-2022 needs to invoke the hook on a bond transfer (fixed order, no RPC). */
export function hookExtraAccounts(mint: PublicKey, destinationOwner: PublicKey, programId = PLAIN_MARKETS_PROGRAM_ID): AccountMeta[] {
  const instrument = pda.instrument(mint, programId);
  return [
    { pubkey: instrument, isSigner: false, isWritable: false },
    { pubkey: pda.allow(instrument, destinationOwner, programId), isSigner: false, isWritable: false },
    { pubkey: programId, isSigner: false, isWritable: false },
    { pubkey: pda.extraAccountMetas(mint, programId), isSigner: false, isWritable: false },
  ];
}

/** Create the recipient's bond ATA (idempotent) and transfer units with the hook accounts attached. */
export function bondTransferInstructions(args: {
  payer: PublicKey;
  mint: PublicKey;
  from: PublicKey;
  to: PublicKey;
  units: bigint;
  programId?: PublicKey;
}): TransactionInstruction[] {
  const { payer, mint, from, to, units } = args;
  const create = createAssociatedTokenAccountIdempotentInstruction(payer, bondAta(to, mint), to, mint, TOKEN_2022_PROGRAM_ID);
  const transfer = createTransferCheckedInstruction(bondAta(from, mint), mint, bondAta(to, mint), from, units, 0, [], TOKEN_2022_PROGRAM_ID);
  transfer.keys.push(...hookExtraAccounts(mint, to, args.programId));
  return [create, transfer];
}

// ---- program ----------------------------------------------------------------------------------------

/** Read-only programs need only a connection; signing flows pass an AnchorProvider. */
export function marketsProgram(providerOrConnection: Provider | Connection, idl: PlainMarkets = PLAIN_MARKETS_IDL): Program<PlainMarkets> {
  const provider =
    "connection" in providerOrConnection && "publicKey" in providerOrConnection
      ? (providerOrConnection as Provider)
      : ({ connection: providerOrConnection as Connection } as Provider);
  return new Program<PlainMarkets>(idl, provider);
}

export type InstrumentRef = { address: PublicKey; account: InstrumentAccount };
export type ActionRef = { address: PublicKey; account: CorporateActionAccount };

export type InstrumentInput = {
  name: string;
  symbol: string;
  uri: string;
  /** 12-char ISIN, or empty. */
  isin: string;
  faceValue: bigint;
  couponBps: number;
  couponFrequency: 1 | 2 | 4 | 12;
  issueTs: number;
  maturityTs: number;
  allowlistEnabled: boolean;
  payingAgent?: PublicKey | null;
};

export type AnnounceInput = {
  kind: ActionKind;
  title: string;
  termsHash: Uint8Array;
  recordTs: number;
  paymentTs: number;
  claimDeadline: number;
  rateBps?: number;
  redeemBps?: number;
  priceBps?: number;
  options?: string[];
};

export type SnapshotInput = {
  merkleRoot: Uint8Array;
  snapshotHash: Uint8Array;
  totalUnits: bigint;
  holderCount: number;
  totalRedeemUnits?: bigint;
};

export class MarketsClient {
  readonly coder: BorshCoder;
  readonly events: EventParser;

  constructor(readonly program: Program<PlainMarkets>) {
    this.coder = new BorshCoder(program.idl);
    this.events = new EventParser(program.programId, this.coder);
  }

  static fromConnection(connection: Connection) {
    return new MarketsClient(marketsProgram(connection));
  }

  static fromProvider(provider: AnchorProvider) {
    return new MarketsClient(marketsProgram(provider));
  }

  get programId() {
    return this.program.programId;
  }

  // ---- reads ----------------------------------------------------------------------------------------

  async fetchInstrument(address: PublicKey): Promise<InstrumentRef | null> {
    const account = await this.program.account.instrument.fetchNullable(address);
    return account ? { address, account } : null;
  }

  fetchInstrumentByMint(mint: PublicKey) {
    return this.fetchInstrument(pda.instrument(mint, this.programId));
  }

  async listInstruments(issuer?: PublicKey): Promise<InstrumentRef[]> {
    // issuer is the first field after the 8-byte discriminator.
    const filters = issuer ? [{ memcmp: { offset: 8, bytes: issuer.toBase58() } }] : [];
    const rows = await this.program.account.instrument.all(filters);
    return rows.map((r) => ({ address: r.publicKey, account: r.account }));
  }

  async fetchAction(address: PublicKey): Promise<ActionRef | null> {
    const account = await this.program.account.corporateAction.fetchNullable(address);
    return account ? { address, account } : null;
  }

  /** All actions of an instrument by id (derived PDAs, one getMultipleAccounts). */
  async listActions(instrument: InstrumentRef): Promise<ActionRef[]> {
    const count = Number(toBigInt(instrument.account.actionCount));
    const addresses = Array.from({ length: count }, (_, i) => pda.action(instrument.address, i, this.programId));
    if (addresses.length === 0) return [];
    const accounts = await this.program.account.corporateAction.fetchMultiple(addresses);
    return accounts.flatMap((account, i) => (account ? [{ address: addresses[i], account }] : []));
  }

  async listReceipts(action: PublicKey) {
    // ClaimReceipt.action is the first field.
    const rows = await this.program.account.claimReceipt.all([{ memcmp: { offset: 8, bytes: action.toBase58() } }]);
    return rows.map((r) => ({ address: r.publicKey, account: r.account }));
  }

  async listVotes(action: PublicKey) {
    const rows = await this.program.account.voteRecord.all([{ memcmp: { offset: 8, bytes: action.toBase58() } }]);
    return rows.map((r) => ({ address: r.publicKey, account: r.account }));
  }

  /** Decodes every plain_markets event in a transaction's log messages. */
  parseEvents(logs: string[]): MarketsEvent[] {
    return [...this.events.parseLogs(logs)] as MarketsEvent[];
  }

  // ---- issuer: instrument ----------------------------------------------------------------------------

  initializeInstrument(args: {
    issuer: PublicKey;
    mint: PublicKey;
    settlementMint: PublicKey;
    settlementTokenProgram: PublicKey;
    params: InstrumentInput;
  }) {
    const { issuer, mint, settlementMint, settlementTokenProgram, params } = args;
    const isin = new Uint8Array(12);
    isin.set(enc(params.isin).slice(0, 12));
    return this.program.methods
      .initializeInstrument({
        name: params.name,
        symbol: params.symbol,
        uri: params.uri,
        isin: Array.from(isin),
        faceValue: bn(params.faceValue),
        couponBps: params.couponBps,
        couponFrequency: params.couponFrequency,
        issueTs: bn(params.issueTs),
        maturityTs: bn(params.maturityTs),
        allowlistEnabled: params.allowlistEnabled,
        payingAgent: params.payingAgent ?? null,
      })
      .accountsStrict({
        issuer,
        mint,
        instrument: pda.instrument(mint, this.programId),
        extraAccountMetaList: pda.extraAccountMetas(mint, this.programId),
        settlementMint,
        settlementTokenProgram,
        tokenProgram: TOKEN_2022_PROGRAM_ID,
        systemProgram: SystemProgram.programId,
      })
      .instruction();
  }

  issue(instrument: InstrumentRef, holder: PublicKey, units: bigint) {
    const { mint, issuer } = instrument.account;
    return this.program.methods
      .issue(bn(units))
      .accountsStrict({
        issuer,
        instrument: instrument.address,
        mint,
        holder,
        holderToken: bondAta(holder, mint),
        allowEntry: instrument.account.allowlistEnabled ? pda.allow(instrument.address, holder, this.programId) : null,
        tokenProgram: TOKEN_2022_PROGRAM_ID,
        associatedTokenProgram: ASSOCIATED_TOKEN_PROGRAM_ID,
        systemProgram: SystemProgram.programId,
      })
      .instruction();
  }

  allowHolder(instrument: InstrumentRef, wallet: PublicKey) {
    return this.program.methods
      .allowHolder(wallet)
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        allowEntry: pda.allow(instrument.address, wallet, this.programId),
        systemProgram: SystemProgram.programId,
      })
      .instruction();
  }

  disallowHolder(instrument: InstrumentRef, wallet: PublicKey) {
    return this.program.methods
      .disallowHolder()
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        allowEntry: pda.allow(instrument.address, wallet, this.programId),
      })
      .instruction();
  }

  setAllowlist(instrument: InstrumentRef, enabled: boolean) {
    return this.program.methods
      .setAllowlist(enabled)
      .accountsStrict({ issuer: instrument.account.issuer, instrument: instrument.address })
      .instruction();
  }

  // ---- primary offering ------------------------------------------------------------------------------

  async fetchOffering(instrument: PublicKey): Promise<{ address: PublicKey; account: OfferingAccount } | null> {
    const address = pda.offering(instrument, this.programId);
    const account = await this.program.account.offering.fetchNullable(address);
    return account ? { address, account } : null;
  }

  openOffering(instrument: InstrumentRef, params: { issuePrice: bigint; startTs: bigint; endTs: bigint; capUnits: bigint; perHolderCap: bigint }) {
    return this.program.methods
      .openOffering({
        issuePrice: bn(params.issuePrice),
        startTs: bn(params.startTs),
        endTs: bn(params.endTs),
        capUnits: bn(params.capUnits),
        perHolderCap: bn(params.perHolderCap),
      })
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        offering: pda.offering(instrument.address, this.programId),
        proceedsVault: pda.proceeds(instrument.address, this.programId),
        settlementMint: instrument.account.settlementMint,
        settlementTokenProgram: instrument.account.settlementTokenProgram,
        systemProgram: SystemProgram.programId,
      })
      .instruction();
  }

  /** DvP purchase. The buyer's bond ATA must exist (create it idempotently in the same transaction). */
  subscribe(instrument: InstrumentRef, buyer: PublicKey, units: bigint, maxPayment: bigint) {
    const { mint, settlementMint, settlementTokenProgram } = instrument.account;
    return this.program.methods
      .subscribe(bn(units), bn(maxPayment))
      .accountsStrict({
        buyer,
        instrument: instrument.address,
        offering: pda.offering(instrument.address, this.programId),
        mint,
        buyerBond: bondAta(buyer, mint),
        buyerSettlement: getAssociatedTokenAddressSync(settlementMint, buyer, true, settlementTokenProgram),
        proceedsVault: pda.proceeds(instrument.address, this.programId),
        settlementMint,
        allowEntry: instrument.account.allowlistEnabled ? pda.allow(instrument.address, buyer, this.programId) : null,
        tokenProgram: TOKEN_2022_PROGRAM_ID,
        settlementTokenProgram,
      })
      .instruction();
  }

  withdrawProceeds(instrument: InstrumentRef, amount: bigint) {
    const { issuer, settlementMint, settlementTokenProgram } = instrument.account;
    return this.program.methods
      .withdrawProceeds(bn(amount))
      .accountsStrict({
        issuer,
        instrument: instrument.address,
        offering: pda.offering(instrument.address, this.programId),
        proceedsVault: pda.proceeds(instrument.address, this.programId),
        issuerSettlement: getAssociatedTokenAddressSync(settlementMint, issuer, true, settlementTokenProgram),
        settlementMint,
        settlementTokenProgram,
      })
      .instruction();
  }

  closeOffering(instrument: InstrumentRef) {
    return this.program.methods
      .closeOffering()
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        offering: pda.offering(instrument.address, this.programId),
      })
      .instruction();
  }

  setPayingAgent(instrument: InstrumentRef, payingAgent: PublicKey) {
    return this.program.methods
      .setPayingAgent(payingAgent)
      .accountsStrict({ issuer: instrument.account.issuer, instrument: instrument.address })
      .instruction();
  }

  // ---- corporate-action lifecycle --------------------------------------------------------------------

  /** Returns the instruction and the new action address (id = instrument.actionCount). */
  async announce(instrument: InstrumentRef, input: AnnounceInput) {
    const action = pda.action(instrument.address, toBigInt(instrument.account.actionCount), this.programId);
    const pays = input.kind !== "Vote";
    const ix = await this.program.methods
      .announce({
        kind: enumArg(input.kind),
        title: input.title,
        termsHash: bytes32(input.termsHash),
        recordTs: bn(input.recordTs),
        paymentTs: bn(input.paymentTs),
        claimDeadline: bn(input.claimDeadline),
        rateBps: input.rateBps ?? 0,
        redeemBps: input.redeemBps ?? 0,
        priceBps: input.priceBps ?? 0,
        options: input.options ?? [],
      })
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        action,
        vault: pays ? pda.vault(action, this.programId) : null,
        settlementMint: pays ? instrument.account.settlementMint : null,
        settlementTokenProgram: pays ? instrument.account.settlementTokenProgram : null,
        systemProgram: SystemProgram.programId,
      })
      .instruction();
    return { ix, action };
  }

  lockRecord(instrument: InstrumentRef, action: PublicKey, cranker: PublicKey) {
    return this.program.methods
      .lockRecord()
      .accountsStrict({ cranker, instrument: instrument.address, action, mint: instrument.account.mint })
      .instruction();
  }

  postSnapshot(instrument: InstrumentRef, action: PublicKey, s: SnapshotInput) {
    return this.program.methods
      .postSnapshot({
        merkleRoot: bytes32(s.merkleRoot),
        snapshotHash: bytes32(s.snapshotHash),
        totalUnits: bn(s.totalUnits),
        holderCount: s.holderCount,
        totalRedeemUnits: bn(s.totalRedeemUnits ?? BigInt(0)),
      })
      .accountsStrict({
        issuer: instrument.account.issuer,
        instrument: instrument.address,
        action,
        mint: instrument.account.mint,
      })
      .instruction();
  }

  fund(instrument: InstrumentRef, action: PublicKey, amount: bigint, issuerSettlement?: PublicKey) {
    const { issuer, settlementMint, settlementTokenProgram } = instrument.account;
    return this.program.methods
      .fund(bn(amount))
      .accountsStrict({
        issuer,
        instrument: instrument.address,
        action,
        vault: pda.vault(action, this.programId),
        issuerSettlement: issuerSettlement ?? getAssociatedTokenAddressSync(settlementMint, issuer, true, settlementTokenProgram),
        settlementMint,
        settlementTokenProgram,
      })
      .instruction();
  }

  private paymentAccounts(instrument: InstrumentRef, action: ActionRef, holder: PublicKey) {
    const { mint, settlementMint, settlementTokenProgram } = instrument.account;
    const burns = "partialRedemption" in action.account.kind || "finalRedemption" in action.account.kind;
    return {
      instrument: instrument.address,
      action: action.address,
      vault: pda.vault(action.address, this.programId),
      holderSettlement: getAssociatedTokenAddressSync(settlementMint, holder, true, settlementTokenProgram),
      mint,
      holderBond: burns ? bondAta(holder, mint) : null,
      receipt: pda.claim(action.address, holder, this.programId),
      settlementMint,
      tokenProgram: TOKEN_2022_PROGRAM_ID,
      settlementTokenProgram,
      associatedTokenProgram: ASSOCIATED_TOKEN_PROGRAM_ID,
      systemProgram: SystemProgram.programId,
    };
  }

  /** Holder pulls its entitlement (holder signs and pays rent for the receipt). */
  claim(instrument: InstrumentRef, action: ActionRef, holder: PublicKey, units: bigint, proof: Uint8Array[]) {
    return this.program.methods
      .claim(bn(units), proof.map(bytes32))
      .accountsStrict({ holder, ...this.paymentAccounts(instrument, action, holder) })
      .instruction();
  }

  /** Paying agent (or issuer) pushes the entitlement to the holder's ATA. */
  pay(instrument: InstrumentRef, action: ActionRef, payingAgent: PublicKey, holder: PublicKey, units: bigint, proof: Uint8Array[]) {
    return this.program.methods
      .pay(bn(units), proof.map(bytes32))
      .accountsStrict({ payingAgent, holder, ...this.paymentAccounts(instrument, action, holder) })
      .instruction();
  }

  castVote(instrument: InstrumentRef, action: PublicKey, holder: PublicKey, units: bigint, proof: Uint8Array[], choice: number) {
    return this.program.methods
      .castVote(bn(units), proof.map(bytes32), choice)
      .accountsStrict({
        holder,
        instrument: instrument.address,
        action,
        voteRecord: pda.vote(action, holder, this.programId),
        systemProgram: SystemProgram.programId,
      })
      .instruction();
  }

  settle(instrument: InstrumentRef, action: ActionRef, authority: PublicKey) {
    const { issuer, settlementMint, settlementTokenProgram } = instrument.account;
    const pays = !("vote" in action.account.kind);
    return this.program.methods
      .settle()
      .accountsStrict({
        authority,
        instrument: instrument.address,
        action: action.address,
        issuer,
        vault: pays ? pda.vault(action.address, this.programId) : null,
        issuerSettlement: pays ? getAssociatedTokenAddressSync(settlementMint, issuer, true, settlementTokenProgram) : null,
        settlementMint: pays ? settlementMint : null,
        settlementTokenProgram: pays ? settlementTokenProgram : null,
      })
      .instruction();
  }

  cancelAction(instrument: InstrumentRef, action: ActionRef) {
    const { issuer, settlementMint, settlementTokenProgram } = instrument.account;
    const pays = !("vote" in action.account.kind);
    return this.program.methods
      .cancelAction()
      .accountsStrict({
        issuer,
        instrument: instrument.address,
        action: action.address,
        vault: pays ? pda.vault(action.address, this.programId) : null,
        issuerSettlement: pays ? getAssociatedTokenAddressSync(settlementMint, issuer, true, settlementTokenProgram) : null,
        settlementMint: pays ? settlementMint : null,
        settlementTokenProgram: pays ? settlementTokenProgram : null,
      })
      .instruction();
  }
}

/** Program error code → name/message, from the IDL. */
export function marketsErrorFromCode(code: number) {
  return idlJson.errors.find((e) => e.code === code) ?? null;
}
